const input = $input.first().json.body || $input.first().json;
const projectId = input.project_id;
const leadId = input.lead_id;
const eventName = input.event_name;
const eventTime = input.event_time || Math.floor(Date.now() / 1000);
const leadData = input.lead_data || {};

if (!projectId) throw new Error('project_id is required');
if (!leadId) throw new Error('lead_id is required');
if (!eventName) throw new Error('event_name is required');

return {
  json: {
    project_id: projectId,
    lead_id: leadId,
    event_name: eventName,
    event_time: typeof eventTime === 'number' ? eventTime : Math.floor(new Date(eventTime).getTime() / 1000),
    value: input.value || leadData.deal_amount || 0,
    currency: input.currency || 'RUB'
  }
};

const inputData = $('Validate Input').first().json;
const leadArray = $('Get Lead Data').first().json;
const pixelArray = $input.first().json;

const lead = Array.isArray(leadArray) ? leadArray[0] : leadArray;
const pixelConfig = Array.isArray(pixelArray) ? pixelArray[0] : pixelArray;

if (!lead) throw new Error('Lead not found');
if (!pixelConfig || !pixelConfig.fb_pixel_id) {
  return { json: { skip: true, reason: 'No pixel configured' } };
}

const crypto = require('crypto');
const hash = (value) => {
  if (!value) return null;
  return crypto.createHash('sha256').update(value.toLowerCase().trim()).digest('hex');
};

const normalizePhone = (phone) => {
  if (!phone) return null;
  let digits = phone.replace(/\\D/g, '');
  if (digits.startsWith('8') && digits.length === 11) digits = '7' + digits.slice(1);
  if (!digits.startsWith('7') && digits.length === 10) digits = '7' + digits;
  return digits;
};

const userData = {
  em: lead.email ? [hash(lead.email)] : undefined,
  ph: lead.phone ? [hash(normalizePhone(lead.phone))] : undefined,
  fn: lead.name ? [hash(lead.name.split(' ')[0])] : undefined,
  ln: lead.name && lead.name.split(' ')[1] ? [hash(lead.name.split(' ')[1])] : undefined,
  fbc: lead.fbc || undefined,
  fbp: lead.fbp || undefined
};
Object.keys(userData).forEach(key => userData[key] === undefined && delete userData[key]);

const customData = {
  value: inputData.value || lead.deal_amount || 0,
  currency: inputData.currency || 'RUB',
  content_name: lead.clinic_name || 'Lead',
  content_category: 'medical'
};

const eventNameMap = {
  'Schedule': 'Schedule', 'schedule': 'Schedule', 'diagnostic': 'Schedule', 'diagnostic_scheduled': 'Schedule',
  'Purchase': 'Purchase', 'purchase': 'Purchase', 'sold': 'Purchase', 'sale': 'Purchase',
  'Lead': 'Lead', 'lead': 'Lead', 'new': 'Lead'
};

const fbEventName = eventNameMap[inputData.event_name] || inputData.event_name;
const eventId = `${lead.id}_${fbEventName}_${inputData.event_time}`;

return {
  json: {
    skip: false,
    pixel_id: pixelConfig.fb_pixel_id,
    access_token: pixelConfig.fb_access_token,
    test_event_code: pixelConfig.fb_test_event_code,
    event: {
      event_name: fbEventName,
      event_time: inputData.event_time,
      event_id: eventId,
      event_source_url: lead.site_url || lead.extra_data?.url,
      action_source: 'website',
      user_data: userData,
      custom_data: customData
    },
    lead_id: lead.id,
    project_id: inputData.project_id,
    fbclid: lead.fbclid,
    fb_ad_id: lead.fb_ad_id,
    fb_campaign_id: lead.fb_campaign_id
  }
};
